                 Some(req) => Some(match req {
                     RequestView::<EReq>::KRequest(api_req) => RequestContent::KubernetesRequest(api_req),
                     RequestView::<EReq>::ExternalRequest(ext_req) => RequestContent::ExternalRequest(ext_req.marshal()),
